package com.shopsmart.api;
import com.shopsmart.api.ApiDtos.*;import com.shopsmart.service.CartService;import jakarta.validation.Valid;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/cart") @SecurityRequirement(name="bearerAuth") public class CartController {private final CartService carts;public CartController(CartService c){carts=c;}@GetMapping public CartResponse get(Authentication a){return ApiMapper.cart(carts.get(a.getName()));}@PostMapping("/items") public CartResponse add(Authentication a,@Valid @RequestBody AddCartRequest r){return ApiMapper.cart(carts.add(a.getName(),r.productId(),r.quantity()));}@PutMapping("/items/{productId}") public CartResponse update(Authentication a,@PathVariable Long productId,@Valid @RequestBody CartQuantityRequest r){return ApiMapper.cart(carts.updateQuantity(a.getName(),productId,r.quantity()));}@DeleteMapping("/items/{productId}") public CartResponse remove(Authentication a,@PathVariable Long productId){return ApiMapper.cart(carts.remove(a.getName(),productId));}@DeleteMapping public void clear(Authentication a){carts.clear(a.getName());}}
